//programs__cards
jQuery(function ($) {
  let $programsSlider = $('.programs__cards');
  function slickify() {
    $programsSlider.slick({
      slidesToShow: 4,
      slidesToScroll: 1,
      arrows: true,
      dots: false,
      autoplay: false,
      infinite: true,
      autoplaySpeed: 5000,
      speed: 500,
      cssEase: "ease-in-out",
      responsive: [
        {
          breakpoint: 1200,
          settings: {
            slidesToShow: 3,
          }
        },
		{
          breakpoint: 992,
          settings: {
            slidesToShow: 2,
          }
        }
      ]
    });
  }

  var slickInitialized = false;

  $(window).on('load resize', function () {
    var windowWidth = $(window).width();
    if (windowWidth >= 768) {
      if (!slickInitialized) {
        slickify();
        slickInitialized = true;
      }
    } else {
      if (slickInitialized) {
        slickInitialized = false;
        $programsSlider.slick('unslick');
      }
    }
  });
});